package net.civeira.phylax.feature.identity.tenantconfig.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.tenantconfig.domain.TenantConfig;
import net.civeira.phylax.feature.identity.tenantconfig.domain.valueobject.ForceMfaVO;

class ForceMfaValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of force mfa of tenant config")
  void test_force_mfa_value_holder_assign_plain_value() {
    Object holder = new Object();
    ForceMfaValueHolder<Object> value = new ForceMfaValueHolder<>(holder);
    Assertions.assertSame(holder, value.forceMfa(true), "Setters must return the holder");
    Assertions.assertTrue(value.getForceMfaValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals(true, value.getForceMfa().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of force mfa of tenant config")
  void test_force_mfa_value_holder_assign_value_object() {
    Object holder = new Object();
    ForceMfaValueHolder<Object> value = new ForceMfaValueHolder<>(holder);
    ForceMfaVO vo = ForceMfaVO.from(true);
    Assertions.assertFalse(value.getForceMfaValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.forceMfa(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getForceMfaValue().orElseThrow());
    Assertions.assertSame(holder, value.forceMfa(Optional.empty()));
    Assertions.assertFalse(value.getForceMfaValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.forceMfa(Optional.of(vo)));
    Assertions.assertSame(vo, value.getForceMfaValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of force mfa of tenant config against the original")
  void test_force_mfa_value_holder_read() {
    Object holder = new Object();
    ForceMfaValueHolder<Object> value = new ForceMfaValueHolder<>(holder);
    ForceMfaVO vo = ForceMfaVO.from(true);
    ForceMfaVO other = ForceMfaVO.from(true);
    TenantConfig original = Mockito.mock(TenantConfig.class);
    Mockito.when(original.getForceMfaValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readForceMfa(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readForceMfa(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.forceMfa(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readForceMfa(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readForceMfa(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of force mfa of tenant config")
  void test_force_mfa_value_holder_unset() {
    Object holder = new Object();
    ForceMfaValueHolder<Object> value = new ForceMfaValueHolder<>(holder);
    ForceMfaVO vo = ForceMfaVO.from(true);
    value.forceMfa(vo);
    Assertions.assertSame(holder, value.unsetForceMfaIfMatches("forceMfa_other"));
    Assertions.assertTrue(value.getForceMfaValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetForceMfaIfMatches("forceMfa"));
    Assertions.assertFalse(value.getForceMfaValue().isPresent(),
        "The field name must clear the value");
    value.forceMfa(vo);
    Assertions.assertSame(holder, value.unsetForceMfa());
    Assertions.assertFalse(value.getForceMfaValue().isPresent(), "Unset must clear the value");
  }
}
